// Dev tool: prints which packages take space in the activity bundle. Usage: node scripts/analyze-bundle.mjs
import { build } from "vite"
import react from "@vitejs/plugin-react"
import tailwindcss from "@tailwindcss/vite"
import { readFileSync, readdirSync } from "node:fs"
const root = process.cwd()
await build({
  root, configFile: false, logLevel: "silent", mode: "activity",
  plugins: [react(), tailwindcss()],
  resolve: { alias: { "@": root + "/src" } },
  define: { __BUILD_INFO__: "{}" },
  build: { outDir: "node_modules/.analyze", sourcemap: true, emptyOutDir: true, rolldownOptions: { input: root + "/index.html" } },
})
const dir = "node_modules/.analyze/assets/"
const mapFile = readdirSync(dir).find((f) => f.endsWith(".js.map"))
const map = JSON.parse(readFileSync(dir + mapFile, "utf8"))
const js = readFileSync(dir + mapFile.replace(".map", ""), "utf8")
// decode VLQ mappings to attribute generated bytes to sources
const chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
const lines = js.split("\n"); const sizes = new Array(map.sources.length).fill(0)
let src = 0
map.mappings.split(";").forEach((seg, li) => {
  let col = 0; const line = lines[li] ?? ""; const entries = []
  for (const s of seg.split(",")) { if (!s) continue; let vals = [], v = 0, shift = 0
    for (const c of s) { let d = chars.indexOf(c); v += (d & 31) << shift; if (d & 32) shift += 5; else { vals.push(v & 1 ? -(v >> 1) : v >> 1); v = 0; shift = 0 } }
    col += vals[0]; if (vals.length > 1) src += vals[1]; entries.push([col, src]) }
  entries.forEach(([c, s], i) => { const end = i + 1 < entries.length ? entries[i + 1][0] : line.length; sizes[s] += end - c })
})
const agg = {}
map.sources.forEach((s, i) => { const m = /(?:node_modules\/|^(?:\.\.\/)+)((?:@[^/]+\/)?[^/.][^/]*)/.exec(s); const k = s.includes("/src/") || s.startsWith("src/") ? s.replace(/^.*?src\//, "src/").replace(/\/[^/]+$/, "/") : m ? m[1] : s; agg[k] = (agg[k] ?? 0) + sizes[i] })
Object.entries(agg).sort((a, b) => b[1] - a[1]).slice(0, 40).forEach(([k, v]) => console.log((v / 1024).toFixed(1).padStart(7), "KB", k))

console.log("total", (Object.values(agg).reduce((a, b) => a + b, 0) / 1024).toFixed(0), "KB")
